/**
 *
 * @param {string} text
 * @param {NodeList} buttons
 * @returns Node
 */
const findButton = (text, buttons) => {
    return Array.from(buttons).find(button => button.innerText.trim() === text);
};

/**
 * Checks if an element is selected by examining its dataset
 * @param {HTMLElement} element - Element to check selection status
 * @returns {boolean} Whether the element is selected
 */
const isSelected = (element) => {
    return element.dataset.selected !== undefined;
};

/**
 * Gets the last matching request from pretender handled requests
 * @param {Array} requests - Array of handled requests
 * @param {string} urlPattern - Pattern to match in request URLs
 * @param {string} method - HTTP method to filter by
 * @returns {Object|null} Last matching request or null
 */
const getLastMatchingRequest = (requests, urlPattern, method = 'GET') => {
    const matchingRequests = requests.filter(r => r.url.includes(urlPattern) && r.method === method);
    return matchingRequests[matchingRequests.length - 1] || null;
};

/**
 * Gets the last request from pretender handled requests
 * @param {Object} pretender - Pretender instance
 * @returns {Object} Last handled request
 */
const getLastRequest = (pretender) => {
    const requests = pretender.handledRequests;
    return requests[requests.length - 1] || {};
};

/**
 * Gets all posts-related requests from pretender
 * @param {Object} pretender - Pretender instance
 * @returns {Array} Filtered array of posts requests
 */
const getPostsRequests = (pretender) => {
    return pretender.handledRequests.filter(r => r.url.includes('/posts/') && r.method === 'GET');
};

/**
 * Gets all pages-related requests from pretender
 * @param {Object} pretender - Pretender instance
 * @returns {Array} Filtered array of pages requests
 */
const getPagesRequests = (pretender) => {
    return pretender.handledRequests.filter(r => r.url.includes('/pages/') && r.method === 'GET');
};

