import ctrlOrCmd from 'ghost-admin/utils/ctrl-or-cmd';
import sinon from 'sinon';
import windowProxy from 'ghost-admin/utils/window-proxy';
import {authenticateSession, invalidateSession} from 'ember-simple-auth/test-support';
import {beforeEach, describe, it} from 'mocha';
import {blur, click, currentURL, fillIn, find, findAll, triggerEvent, triggerKeyEvent, visit} from '@ember/test-helpers';
import {clickTrigger, selectChoose, selectSearch} from 'ember-power-select/test-support/helpers';
import {expect} from 'chai';
import {setupApplicationTest} from 'ember-mocha';
import {setupMirage} from 'ember-cli-mirage/test-support';

/**
 *
 * @param {string} text
 * @param {NodeList} buttons
 * @returns Node
 */
const findButton = (text, buttons) => {
    return Array.from(buttons).find(button => button.innerText.trim() === text);
};

/**
 * Checks if a post container is selected by examining its dataset
 * @param {HTMLElement} container - The post container element
 * @returns {boolean} Whether the post is selected
 */
function isPostSelected(container) {
    return container.dataset.selected !== undefined;
}

/**
 * Gets the title text from a post element
 * @param {HTMLElement} post - The post element
 * @returns {string} The post title text
 */
function getPostTitle(post) {
    return post.querySelector('.gh-content-entry-title').textContent;
}

/**
 * Gets the status text from a post element
 * @param {HTMLElement} post - The post element
 * @returns {string} The post status text
 */
function getPostStatus(post) {
    return post.querySelector('.gh-content-entry-status').textContent;
}

/**
 * Finds a post container by ID
 * @param {string} postId - The ID of the post
 * @returns {HTMLElement} The post container element
 */
function findPostContainerById(postId) {
    const post = find(`[data-test-post-id="${postId}"]`);
    return post ? post.parentElement : null;
}

/**
 * Clicks on a post with modifier keys for selection
 * @param {HTMLElement} postContainer - The post container to click
 * @returns {Promise<void>}
 */
async function selectPostWithModifierKeys(postContainer) {
    await click(postContainer, {metaKey: ctrlOrCmd === 'command', ctrlKey: ctrlOrCmd === 'ctrl'});
}

/**
 * Triggers context menu event on a post
 * @param {HTMLElement} post - The post element
 * @returns {Promise<void>}
 */
async function openPostContextMenu(post) {
    await triggerEvent(post, 'contextmenu');
}

/**
 * Finds a button in the context menu by text
 * @param {string} buttonText - Text to search for
 * @returns {HTMLElement|null} The matching button or null
 */
function findContextMenuItem(buttonText) {
    const contextMenu = find('.gh-posts-context-menu');
    if (!contextMenu) return null;

    const buttons = contextMenu.querySelectorAll('button');
    return findButton(buttonText, buttons);
}

/**
 * Validates that a post exists in the DOM
 * @param {string} postId - The ID of the post to validate
 * @param {string} description - Description for assertion message
 */
function validatePostExists(postId, description) {
    const post = find(`[data-test-post-id="${postId}"]`);
    expect(post, description).to.exist;
}

/**
 * Validates that context menu is not visible
 */
function validateContextMenuNotVisible() {
    const contextMenu = find('.gh-posts-context-menu');
    expect(contextMenu, 'context menu').to.not.be.visible;
}

/**
 * Validates that context menu is visible
 */
function validateContextMenuVisible() {
    const contextMenu = find('.gh-posts-context-menu');
    expect(contextMenu, 'context menu').to.exist;
}

/**
 * Validates context menu button count and labels
 * @param {number} expectedCount - Expected number of buttons
 * @param {Array<string>} expectedLabels - Expected button labels
 */
function validateContextMenuButtons(expectedCount, expectedLabels) {
    const contextMenu = find('.gh-posts-context-menu');
    const buttons = contextMenu.querySelectorAll('button');
    expect(buttons.length, 'context menu buttons').to.equal(expectedCount);

    expectedLabels.forEach((label, index) => {
        expect(buttons[index].innerText.trim(), `context menu button ${index + 1}`).to.contain(label);
    });
}

/**
 * Performs bulk action on selected posts via context menu
 * @param {string} actionText - Text of the action button to click
 * @returns {Promise<void>}
 */
async function performBulkAction(actionText) {
    const actionButton = findContextMenuItem(actionText);
    expect(actionButton, `${actionText.toLowerCase()} button`).to.exist;
    await click(actionButton);
}

/**
 * Validates API request for bulk operations
 * @param {Object} server - Mirage server instance
 * @param {string} expectedFilter - Expected filter query parameter
 * @param {string} expectedAction - Expected bulk action
 */
function validateBulkOperationRequest(server, expectedFilter, expectedAction) {
    const [lastRequest] = server.pretender.handledRequests.slice(-1);
    expect(lastRequest.queryParams.filter, `${expectedAction} request id`).to.equal(expectedFilter);
    expect(JSON.parse(lastRequest.requestBody).bulk.action, `${expectedAction} request action`).to.equal(expectedAction);
}

/**
 * Validates that posts are featured/unfeatured in UI
 * @param {HTMLElement} postContainer1 - First post container
 * @param {HTMLElement} postContainer2 - Second post container
 * @param {boolean} shouldBeFeatured - Whether posts should be featured
 */
function validatePostFeaturedState(postContainer1, postContainer2, shouldBeFeatured) {
    const featuredCheck1 = postContainer1.querySelector('.gh-featured-post');
    const featuredCheck2 = postContainer2.querySelector('.gh-featured-post');

    if (shouldBeFeatured) {
        expect(featuredCheck1, 'post featured').to.exist;
        expect(featuredCheck2, 'post featured').to.exist;
    } else {
        expect(featuredCheck1, 'post featured').to.not.exist;
        expect(featuredCheck2, 'post featured').to.not.exist;
    }
}

/**
 * Opens change access modal via context menu
 * @returns {Promise<void>}
 */
async function openChangeAccessModal() {
    await performBulkAction('Change access');
}

/**
 * Fills and confirms access change in modal
 * @param {string} accessValue - Access value to set
 * @returns {Promise<void>}
 */
async function setAndConfirmAccess(accessValue) {
    const changeAccessModal = find('[data-test-modal="edit-posts-access"]');
    const selectElement = changeAccessModal.querySelector('select');
    await fillIn(selectElement, accessValue);
    await click('[data-test-button="confirm"]');
}

